package controller;

import constants.Message;
import dto.SalaryHistoryResponseDTO;
import dto.WorkerRequestDTO;
import java.util.List;
import repository.WorkerRepository;
import service.WorkerService;
import view.WorkerView;

/**
 * Dieu phoi: nhan phieu DTO tu Main, goi Repository (CRUD), dua du lieu cho Service tinh,
 * roi dua ket qua cho View in — 1 lan cho 1 luong. Khong nhap, khong in, khong import model.
 *
 * @author CuongThai Academy
 */
public class WorkerController {

    // Kho cong nhan (CRUD o Controller, khong o Service)
    private WorkerRepository workerRepository;

    // Nghiep vu luong
    private WorkerService workerService;

    // Man hinh in ket qua
    private WorkerView workerView;

    // Constructor: tao repository, service va view
    public WorkerController() {
        workerRepository = new WorkerRepository();
        workerService = new WorkerService();
        workerView = new WorkerView();
    }

    // Chuc nang 1: luu cong nhan Main da kiem (ma trung thi kho nem loi, Main in)
    public void addWorker(WorkerRequestDTO workerRequestDTO) throws Exception {
        workerRepository.addWorker(workerRequestDTO);

        // Bao them thanh cong
        workerView.setMessage(String.format(Message.ADD_SUCCESS, workerRequestDTO.getCode()));
        workerView.display();
    }

    // Chuc nang 2, 3: kho tim cong nhan, Service tang/giam + ghi lich su, View bao luong moi
    public void changeSalary(WorkerRequestDTO workerRequestDTO) throws Exception {
        String newSalary = workerService.changeSalary(
                workerRepository.findWorker(workerRequestDTO.getCode()), workerRequestDTO);

        // Bao luong moi
        workerView.setMessage(String.format(Message.CHANGE_SUCCESS, workerRequestDTO.getCode(),
                newSalary));
        workerView.display();
    }

    // Chuc nang 4: kho lay het cong nhan, Service dung bang sap theo ma, View in
    public void displaySalaryHistory() {
        List<SalaryHistoryResponseDTO> historyList
                = workerService.getInfomationSalary(workerRepository.getWorkerList());

        // Chua co lan doi luong nao thi bao, co thi in bang
        if (historyList.isEmpty()) {
            workerView.setMessage(Message.NO_HISTORY);
        } else {
            // Co lich su: dua bang cho view
            workerView.setHistoryList(historyList);
        }

        workerView.display();
    }
}

