        worker = new Worker(workerRequestDTO.getCode(), workerRequestDTO.getName(),
                workerRequestDTO.getAge(), workerRequestDTO.getSalary(),
                workerRequestDTO.getWorkLocation());
        workerMap.put(worker.getCode(), worker);
