    public Worker findWorker(String code) throws Exception {
        Worker worker = workerMap.get(code);

        // Khong co ma nay trong kho
        if (worker == null) {
            throw new Exception(String.format(Message.CODE_NOT_EXIST, code));
        }

        return worker;
    }

