package service;

import constants.Constants;
import constants.Message;
import constants.SalaryStatus;
import dto.SalaryHistoryResponseDTO;
import dto.WorkerRequestDTO;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import model.SalaryHistory;
import model.Worker;
import utils.FormatUtils;

/**
 * Nghiep vu luong: tinh luong moi + ghi lich su, dung bang lich su sap theo ma.
 * Chi xu ly du lieu Controller dua vao — KHONG giu va KHONG goi Repository.
 *
 * @author CuongThai Academy
 */
public class WorkerService {

    // Cach in ngay giong de bai (dd/MM/yyyy) — cong cu, khong phai du lieu
    private DateTimeFormatter dateFormatter;

    // Constructor: tao bo dinh dang ngay; service khong giu cong nhan nao
    public WorkerService() {
        dateFormatter = DateTimeFormatter.ofPattern(Constants.DATE_FORMAT);
    }

    // Tang/giam luong cong nhan theo phieu (de: changeSalary), ghi 1 dong lich su,
    // tra ve luong moi DA DINH DANG (String: Controller chi can chu de bao lai)
    public String changeSalary(Worker worker, WorkerRequestDTO workerRequestDTO)
            throws Exception {
        double newSalary = worker.getSalary() + workerRequestDTO.getAmount();

        // Giam luong: tru di, va luong moi phai con lon hon 0
        if (workerRequestDTO.getStatus() == SalaryStatus.DOWN) {
            newSalary = worker.getSalary() - workerRequestDTO.getAmount();

            // Giam het luong (hoac am) thi khong cho
            if (newSalary <= 0) {
                throw new Exception(String.format(Message.SALARY_NOT_ENOUGH, worker.getCode(),
                        FormatUtils.formatMoney(worker.getSalary())));
            }
        }

        worker.setSalary(newSalary);
        worker.addSalaryHistory(new SalaryHistory(newSalary, workerRequestDTO.getStatus(),
                LocalDate.now()));
        return FormatUtils.formatMoney(newSalary);
    }

    // Bang lich su luong (de: getInfomationSalary): sap cong nhan theo ma, moi lan doi 1 dong
    public List<SalaryHistoryResponseDTO> getInfomationSalary(List<Worker> workerList) {
        List<SalaryHistoryResponseDTO> rowList = new ArrayList<>();

        // Sap theo ma (de: "sort by id"), ghi de compare() cua Comparator
        Collections.sort(workerList, new Comparator<Worker>() {
            // So 2 cong nhan theo ma
            @Override
            public int compare(Worker first, Worker second) {
                return first.getCode().compareTo(second.getCode());
            }
        });

        // Moi cong nhan, moi lan doi luong la 1 dong (giu thu tu thoi gian)
        for (Worker worker : workerList) {
            // Doi tung lan doi luong thanh 1 dong bang
            for (SalaryHistory salaryHistory : worker.getSalaryHistoryList()) {
                rowList.add(toResponseDTO(worker, salaryHistory));
            }
        }

        return rowList;
    }

    // Doi 1 lan doi luong thanh 1 dong bang da dinh dang san de View in
    private SalaryHistoryResponseDTO toResponseDTO(Worker worker, SalaryHistory salaryHistory) {
        SalaryHistoryResponseDTO responseDTO = new SalaryHistoryResponseDTO();

        responseDTO.setCode(worker.getCode());
        responseDTO.setName(worker.getName());
        responseDTO.setAge(worker.getAge());
        responseDTO.setSalary(FormatUtils.formatMoney(salaryHistory.getSalary()));
        responseDTO.setStatus(salaryHistory.getStatus().name());
        responseDTO.setDate(salaryHistory.getDate().format(dateFormatter));
        return responseDTO;
    }
}

