package utils;

import constants.Constants;
import constants.Message;

/**
 * Kiem chu nguoi dung go (Main doc ban phim roi dua vao day). Sai thi nem Exception kem
 * cau bao loi cu the; dung thi tra ve gia tri da lam sach. Khong doc ban phim, khong in.
 *
 * @author CuongThai Academy
 */
public final class Validation {

    // Constructor private: lop chi co ham static
    private Validation() {
    }

    // Kiem lua chon menu la so nguyen trong [min, max]
    public static int getChoice(String input, int min, int max) throws Exception {
        int choice = 0;

        // Doi chuoi sang so nguyen (bo dau cach 2 dau)
        try {
            choice = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu hoac de trong
            throw new Exception(Message.INVALID_NUMBER);
        }

        // Ngoai khoang cho phep thi bao khoang dung
        if ((choice < min) || (choice > max)) {
            throw new Exception(String.format(Message.INVALID_RANGE, min, max));
        }

        return choice;
    }

    // Kiem o chu khong rong (sau khi bo dau cach); rong thi bao dung cau loi cua o do
    public static String getRequired(String input, String errorMessage) throws Exception {
        // Toan dau cach cung tinh la rong
        if (input.trim().isEmpty()) {
            throw new Exception(errorMessage);
        }

        return input.trim();
    }

    // Kiem tuoi la so nguyen tu 18 den 50
    public static int getAge(String input) throws Exception {
        int age = 0;

        // Doi chuoi sang so nguyen
        try {
            age = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu hoac de trong
            throw new Exception(Message.INVALID_NUMBER);
        }

        // Ngoai 18..50 thi bao khoang dung
        if ((age < Constants.MIN_AGE) || (age > Constants.MAX_AGE)) {
            throw new Exception(String.format(Message.AGE_RANGE, Constants.MIN_AGE,
                    Constants.MAX_AGE));
        }

        return age;
    }

    // Kiem so tien la so thuc lon hon 0; khong duong thi bao dung cau loi cua o do
    public static double getPositiveMoney(String input, String errorMessage) throws Exception {
        double money = 0;

        // Doi chuoi sang so thuc
        try {
            money = Double.parseDouble(input.trim());
        } catch (NumberFormatException e) {
            // Go chu hoac de trong
            throw new Exception(Message.INVALID_NUMBER);
        }

        // Bang 0 hoac am thi bao loi cua o dang nhap
        if (money <= 0) {
            throw new Exception(errorMessage);
        }

        return money;
    }
}

